#include "so101_gazebo_demo/pick_place/state_action.hpp"
namespace so101_gazebo_demo::pick_place { void StateActionRegistry::registerPlanner(State s,std::shared_ptr<IStatePlanner> p){planners_[s]=std::move(p);} void StateActionRegistry::registerExecutor(State s,std::shared_ptr<IStateExecutor> e){executors_[s]=std::move(e);} IStatePlanner* StateActionRegistry::findPlanner(State s)const noexcept{auto i=planners_.find(s);return i==planners_.end()?nullptr:i->second.get();} IStateExecutor* StateActionRegistry::findExecutor(State s)const noexcept{auto i=executors_.find(s);return i==executors_.end()?nullptr:i->second.get();} }
